import { sql } from 'drizzle-orm';
import {
  bigint,
  boolean,
  check,
  date,
  index,
  pgTable,
  text,
  timestamp,
  uuid,
} from 'drizzle-orm/pg-core';
import { datingOptions } from './content';
import { bandEnum, localeEnum, modeEnum, userStatusEnum } from './enums';

export { localeEnum, userStatusEnum } from './enums';

/**
 * `id` is a uuid v7 generated by the app. `age_band` is a cache: a trigger re-derives it from
 * `birth_date` on every write (migration 0003), and safety checks never rely on it alone.
 * `birth_date` is write-once (trigger) except through admin_set_birth_date().
 */
export const users = pgTable(
  'users',
  {
    id: uuid('id').primaryKey(),
    telegramId: bigint('telegram_id', { mode: 'number' }).notNull().unique(),
    publicId: text('public_id').notNull().unique(),
    locale: localeEnum('locale').notNull(),
    /** Set when the user picks a language on the first screen (Q13). */
    localeConfirmedAt: timestamp('locale_confirmed_at', { withTimezone: true }),
    status: userStatusEnum('status').notNull().default('onboarding'),
    birthDate: date('birth_date', { mode: 'string' }),
    ageBand: bandEnum('age_band'),
    mode: modeEnum('mode'),
    gender: text('gender').references(() => datingOptions.id),
    seeking: text('seeking').array(),
    username: text('username'),
    timezone: text('timezone'),
    botReachable: boolean('bot_reachable').notNull().default(true),
    onboardedAt: timestamp('onboarded_at', { withTimezone: true }),
    lastActiveAt: timestamp('last_active_at', { withTimezone: true }).notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    check('users_telegram_id_positive', sql`${t.telegramId} > 0`),
    check('users_public_id_format', sql`${t.publicId} ~ '^[0-9A-HJKMNP-TV-Z]{10}$'`),
    // Safety: u18 users are friends-only, and only adults may have a stored username.
    // coalesce: a NULL age_band (no birth date, under 14) must never count as 'adult'.
    check(
      'users_mode_band',
      sql`${t.mode} IS NULL OR ${t.mode} = 'friends' OR coalesce(${t.ageBand} = 'adult', false)`,
    ),
    check(
      'users_username_adult',
      sql`${t.username} IS NULL OR coalesce(${t.ageBand} = 'adult', false)`,
    ),
    check('users_mode_needs_band', sql`${t.mode} IS NULL OR ${t.ageBand} IS NOT NULL`),
    check('users_band_needs_birth_date', sql`${t.ageBand} IS NULL OR ${t.birthDate} IS NOT NULL`),
    // Dating fields exist exactly when the mode is dating (Q11).
    check(
      'users_dating_fields',
      sql`coalesce(${t.mode} = 'dating', false) = (${t.gender} IS NOT NULL AND ${t.seeking} IS NOT NULL)`,
    ),
    check('users_seeking_not_empty', sql`${t.seeking} IS NULL OR cardinality(${t.seeking}) >= 1`),
    // Under-14 (Q16): nothing beyond the account itself, the birth date and the status.
    check(
      'users_ineligible_minimal',
      sql`${t.status} <> 'ineligible' OR (${t.mode} IS NULL AND ${t.gender} IS NULL AND ${t.seeking} IS NULL AND ${t.username} IS NULL AND ${t.timezone} IS NULL AND ${t.onboardedAt} IS NULL)`,
    ),
    index('users_pool_idx').on(t.ageBand, t.locale, t.mode, t.status),
  ],
);
